Given a 2D array arr[][] of order nx2, representing n intervals with start and end points, the task is to find the maximal set of mutually disjoint intervalsNote: Two intervals [i, j] & [k, l] are said to be disjoint if they do not have any point in common. Examples:  Input: arr[][] = [[1, 4], [2, 3], [4, 6], [8, 9]]Output: 2 3 4 6 8 9 Explanation: if [1, 4] is included then we cannot include [2, 3] & [4, 6]. Input: arr[][] = [[1, 9], [2, 3], [5, 7]]Output: 2 35 7Try It YourselfThis problem is mainly a variation of Activity Selection Problem.[Naive Approach] Generate All Subsets - O(n^2 * 2^n) Time and O(n) SpaceGenerate all subsets of the given set of intervals.Check if a subset contains only mutually disjoint intervals by comparing start and end times.Keep track of the largest valid subset.
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Function to check if a subs 
// of intervals is mutually disjoint
bool isDisj(vector<vector<int>> &subs) {
    int n = subs.size();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {

            // If there is any overlapping
            if (subs[i][1] > subs[j][0] &&
                subs[i][0] < subs[j][1])
                return false; 
        }
    }
    return true;
}

// Function to find the maximal set of mutually
// disjoint intervals
vector<vector<int>> maxDisj(vector<vector<int>> &arr) {
    int n = arr.size();
    vector<vector<int>> res;

    // Generate all subsets using bitmasking
    int subCnt = (1 << n);
    for (int mask = 0; mask < subCnt; mask++) {
        vector<vector<int>> subs;

        // Form subs based on mask bits
        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                subs.push_back(arr[i]);
            }
        }

        // Check if the subs is disjoint
        if (isDisj(subs) && subs.size() > res.size()) {
            res = subs; 
        }
    }

    return res;
}

// Driver code
int main() {
    vector<vector<int>> arr = {{1, 4}, {2, 3}, {4, 6}, {8, 9}};
    vector<vector<int>> result = maxDisj(arr);

    for (auto &interval : result) {
        cout << interval[0] << " " << interval[1] << endl;
    }

    return 0;
}


