[Expected Approach] Using Greedy Approach - O(n*log(n)) Time and O(1) Space.The idea is to include the intervals with smallest end points as it will allow to include most of the other intervals. To do so, first sort the given array arr[][] based on their end points. Create a 2d array res[][] to store set of intervals and a counter end, initialized with -1, it will store the end point of last included interval. For each index i, check if start point of arr[i] i.e. arr[i][0] is greater than end, if so, add current element in res[] and update end to end point of arr[i] i.e. arr[i][1], else skip the element. 
            C++

    #include <bits/stdc++.h>
using namespace std;


bool comp(const vector<int> &a, const vector<int> &b)
{
    return (a[1] < b[1]);
}

// Function to find maximal disjoint set
vector<vector<int>> getDisjoint(vector<vector<int>> &arr)
{

    // Sort the array of intervals
    // based on second element
    sort(arr.begin(), arr.end(), comp);

    // Stores the end point of the last
    // interval included in the maximal
    int end = -1;

    // Stores the maximal disjoint set
    vector<vector<int>> ans;

    for (int i = 0; i < arr.size(); i++)
    {

        if (arr[i][0] > end)
        {
            ans.push_back(arr[i]);
            end = arr[i][1];
        }
    }

    return ans;
}

// Driver code
int main()
{
    vector<vector<int>> arr = {{1, 4}, {2, 3}, {4, 6}, {8, 9}};
    vector<vector<int>> ans = getDisjoint(arr);
    for (int i = 0; i < ans.size(); i++)
    {
        cout << ans[i][0] << " " << ans[i][1] << endl;
    }
    return 0;
}


